      }
    }

    const normalizedRole = normalizeRole(role);
    if (!isAdminRole(normalizedRole)) {
      console.log(`[OwnerAuth] ${traceId} user authenticated but not owner: userId=${userId} role=${normalizedRole} elapsed=${Date.now() - startedAt}ms`);
